const { app, BrowserWindow } = require('electron');
const { fork } = require('node:child_process');
const fs = require('node:fs');
const path = require('node:path');
const root = path.resolve(__dirname, '..');
let backend, win;
app.commandLine.appendSwitch('autoplay-policy','no-user-gesture-required');
app.setPath('userData', path.join(root, '.local/smoke-electron'));
app.whenReady().then(() => new Promise((resolve, reject) => {
  const timer = setTimeout(() => reject(new Error('Local model smoke test timed out')), 120000);
  backend = fork(path.join(root, 'server.mjs'), [], { cwd: root, env: { ...process.env, ELECTRON_RUN_AS_NODE: '1', PORT: '0', GRIM_DATA_DIR: path.join(root, '.local/smoke-profile') }, stdio: ['ignore','ignore','pipe','ipc'] });
  backend.stderr.on('data', chunk => process.stderr.write(chunk));
  backend.on('message', async message => {
    if (message.type !== 'ready') return;
    try {
      win = new BrowserWindow({ width: 1440, height: 1000, show: false, webPreferences: { nodeIntegration: false, contextIsolation: true, sandbox: true } });
      win.webContents.on('console-message', (event, ...args) => { const message = event.message || args[1]; if (message) console.log('Renderer:', String(message).slice(0, 1500)); });
      await win.loadURL(message.url);
      console.log('Smoke: dashboard loaded');
    await win.webContents.executeJavaScript(`(async()=>{const canvas=document.querySelector('.core-reticle canvas');await new Promise(r=>setTimeout(r,400));const ctx=canvas.getContext('2d'),original=ctx.drawImage.bind(ctx);let draws=0;ctx.drawImage=(...args)=>{draws++;return original(...args)};window.grimDashboardVisible=false;window.dispatchEvent(new CustomEvent('grim-dashboard-visibility',{detail:false}));await new Promise(r=>setTimeout(r,1000));if(draws)throw new Error('Hidden dashboard still renders');window.grimDashboardVisible=true;window.dispatchEvent(new CustomEvent('grim-dashboard-visibility',{detail:true}));await new Promise(r=>setTimeout(r,300));if(!draws)throw new Error('Dashboard animation did not resume');ctx.drawImage=original})()`);
      const result = await win.webContents.executeJavaScript(`(async () => {
        await new Promise((resolve,reject)=>{ let n=0; const t=setInterval(()=>{if(!document.getElementById('shell').classList.contains('hidden')){clearInterval(t);resolve()}else if(++n>100){clearInterval(t);reject(new Error('UI did not unlock'))}},100) });
        if (!document.getElementById('wake-toggle') || !document.getElementById('page-identity') || !document.getElementById('microphone-device') || !document.getElementById('camera-device') || !document.getElementById('microphone-level')) throw new Error('Missing identity or hardware controls');
        if (!document.getElementById('page-core') || !document.getElementById('page-apps') || !document.getElementById('page-chat')) throw new Error('Core, apps, and conversation must be separate');
        await new Promise((resolve,reject)=>{let tries=0;const timer=setInterval(()=>{const mode=document.querySelector('.core-reticle').dataset.renderer;if(mode==='sprite'&&document.querySelector('.core-reticle canvas')?.dataset.sprite==='ready'){clearInterval(timer);resolve()}else if(mode==='fallback'||++tries>150){clearInterval(timer);reject(new Error('Animated Grim asset failed to initialize'))}},100)});
        console.log('Smoke: animated Grim initialized');
        if(getComputedStyle(document.body).backgroundColor !== 'rgb(5, 5, 5)') throw new Error('Black theme not applied');
        console.log('Smoke: UI verified');
        if(document.getElementById('enroll-voice'))throw new Error('Voice enrollment gate must be absent');
        if(!document.getElementById('page-voice'))throw new Error('Voice settings are missing');
        const load = src => new Promise((resolve,reject)=>{const s=document.createElement('script');s.src=src;s.onload=resolve;s.onerror=reject;document.head.append(s)});
        await load('/vendor/vosk.js');
        console.log('Smoke: Vosk library loaded');
        const model=await Vosk.createModel(location.origin+'/models/wake-en.tar.gz',-2);
        console.log('Smoke: Vosk model loaded');
        const recognizer=new model.KaldiRecognizer(16000);
        const waveforms=["",""];
        const results=[];
        for(const encoded of waveforms){
          const bytes=Uint8Array.from(atob(encoded),c=>c.charCodeAt(0));const context=new AudioContext({sampleRate:16000});
          const audio=await context.decodeAudioData(bytes.buffer);const samples=audio.getChannelData(0);await context.close();
          const text=await new Promise((resolve,reject)=>{const timer=setTimeout(()=>reject(new Error('Wake transcription timed out')),20000);const listener=message=>{if(message.result?.text){clearTimeout(timer);recognizer.removeEventListener('result',listener);resolve(message.result.text)}};recognizer.on('result',listener);recognizer.acceptWaveformFloat(samples,16000);recognizer.acceptWaveformFloat(new Float32Array(16000),16000);recognizer.retrieveFinalResult()});
          results.push(text);
        }
        console.log('Smoke: successive synthetic wake results '+JSON.stringify(results));
        const {wakeCommand}=await import('/identity-core.mjs');
        if(!results.every(text=>wakeCommand(text).detected))throw new Error('Hey Grim did not transcribe as the wake phrase');
        recognizer.remove();model.terminate();
        await load('/vendor/human.js'); const Engine=Human.Human||Human.default||Human;
        const human=new Engine({backend:'webgl',modelBasePath:'/vendor/human/models/',face:{enabled:true,detector:{maxDetected:2,rotation:true},mesh:{enabled:true},iris:{enabled:false},description:{enabled:true},emotion:{enabled:false}},body:{enabled:false},hand:{enabled:false},object:{enabled:false},gesture:{enabled:false},segmentation:{enabled:false}});
        await human.load();
        console.log('Smoke: Human model loaded');
        const canvas=document.createElement('canvas');canvas.width=320;canvas.height=240;
        const detected=await human.detect(canvas);
        if(detected.face.length) throw new Error('False face detection on blank input');
        return {wakeModel:true,faceModel:true,voiceGateRemoved:true,animatedCharacter:true,blackGoldTheme:true,identityControls:true};
      })()`);
      const image = await win.webContents.capturePage(); fs.writeFileSync(path.join(root, '.local/command-deck.png'), image.toPNG());
      console.log(JSON.stringify(result)); clearTimeout(timer); resolve();
    } catch (error) { clearTimeout(timer); reject(error); }
  });
  backend.on('error', reject);
})).then(() => { backend?.send('shutdown'); app.exit(0); }).catch(error => { console.error(error); backend?.kill(); app.exit(1); });
app.on('window-all-closed', () => {});
